window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"WdZUDYNqXyI","speaker":"Espen Barth Eide","role":"Foreign Minister","country":"Norway","region":"Europe","url":"https://www.youtube.com/watch?v=WdZUDYNqXyI","date":"20260926","title":"🇳🇴 Norway - Foreign Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1102,"words":2308,"counts":{"claims":32,"promises":4,"attacks":2},"topics":[{"topic":"UN institutional crisis","share":0.174,"seconds":192},{"topic":"UN reform","share":0.1404,"seconds":155},{"topic":"Russia-Ukraine war","share":0.1122,"seconds":124},{"topic":"International justice","share":0.0609,"seconds":67},{"topic":"Gramsci quote","share":0.0596,"seconds":66},{"topic":"Democracy erosion","share":0.0587,"seconds":65},{"topic":"UNSC reform","share":0.0582,"seconds":64},{"topic":"Israel-Gaza conflict","share":0.0573,"seconds":63},{"topic":"UN funding","share":0.0568,"seconds":63},{"topic":"AI governance","share":0.0561,"seconds":62},{"topic":"UN Charter","share":0.0556,"seconds":61},{"topic":"International law","share":0.0553,"seconds":61},{"topic":"Climate change","share":0.0549,"seconds":60}],"timeline":[[5,70,"Gramsci quote"],[72,135,"UN institutional crisis"],[137,198,"UN Charter"],[199,260,"International law"],[261,324,"Israel-Gaza conflict"],[327,390,"UN funding"],[391,459,"UN institutional crisis"],[461,523,"Russia-Ukraine war"],[524,586,"Russia-Ukraine war"],[587,654,"International justice"],[656,717,"UN reform"],[718,783,"UN reform"],[784,848,"UNSC reform"],[850,910,"Climate change"],[912,974,"AI governance"],[975,1039,"Democracy erosion"],[1041,1101,"UN institutional crisis"],[1102,1132,"UN reform"]],"stances":{"Gramsci quote":"Espen Barth Eide introduces a quote by Antonio Gramsci to describe the current era as a time of transition and insecurity.","UN institutional crisis":"Espen Barth Eide states that the United Nations is facing its most serious challenge due to an erosion of respect for international law and a growing belief that power matters more than principle.","UN Charter":"Espen Barth Eide argues that states honoring the UN Charter must be prepared to make difficult reforms because the organization faces a triple crisis and rules are being undermined.","International law":"Espen Barth Eide argues that international law is a necessary system for reducing risk and protecting state integrity, rather than charity for the weak.","Israel-Gaza conflict":"Espen Barth Eide argues that international law must be applied universally to condemn violations by both Russia and Israel, and calls for immediate action to implement a two-state solution.","UN funding":"Espen Barth Eide argues that double standards undermine international law and calls for reduced earmarking of funds to support UN reform.","Russia-Ukraine war":"Espen Barth Eide states that Russia's war against Ukraine disrupts grain and fertilizer supplies, undermining global food security.","International justice":"Espen Barth Eide states that Norway rejects calls to dismantle the International Criminal Court and commits to strengthening it alongside like-minded countries.","UN reform":"Espen Barth Eide supports structural changes to the UN, including merging overlapping organizations, but criticizes member states for prioritizing vested interests over common goals.","UNSC reform":"Espen Barth Eide argues that the UN Security Council requires reform to address its composition, specifically the lack of African representation among permanent seats, and must become open, transparent, accountable, legitimate, and effective.","Climate change":"Espen Barth Eide states that while reducing emissions and managing resources is possible with existing technology, success requires global cooperation rather than isolation.","AI governance":"Espen Barth Eide argues that artificial intelligence must remain under human direction and control while maximizing its benefits and curbing its risks.","Democracy erosion":"Espen Barth Eide states that democratic backsliding, polarization, and weakening of democratic shields are serious trends that negatively impact international cooperation and shared concerns."},"claims":[{"t":46,"quote":"these words stem from the Italian philosopher Antonio Gramsci, written in one of Mussolini's prison cells in the 1930s.","topic":"Gramsci quote","kind":"fact"},{"t":56,"quote":"The monsters he refers to were the dark political, social, and ideological phenomena of his time.","topic":"Gramsci quote","kind":"fact"},{"t":76,"quote":"His era ended with the largest catastrophe of them all, the Second World War.","topic":"UN institutional crisis","kind":"fact"},{"t":83,"quote":"Our United Nations was founded by leaders who had lived through two World a devastating economic collapse, and the rise of fascism and Nazism.","topic":"UN institutional crisis","kind":"fact"},{"t":172,"quote":"Today, the repercussions of ongoing wars are felt across the globe.","topic":"UN Charter","kind":"fact"},{"t":217,"quote":"The number of ongoing wars is alarmingly high. Most dramatically, the number of wars between states is the highest since the United Nations was established.","topic":"International law","kind":"number"},{"t":234,"quote":"To save succeeding generations from the scourge of war.","topic":"International law","kind":"fact"},{"t":264,"quote":"Its closure raises energy prices, disrupts global supply lines, and curbs growth far beyond the region itself.","topic":"Israel-Gaza conflict","kind":"fact"},{"t":272,"quote":"From petrol pumps in Minneapolis to Oslo, from Cape Town to Mumbai.","topic":"Israel-Gaza conflict","kind":"fact"},{"t":306,"quote":"At this General Assembly, there's been a record number of Palestine-related","topic":"Israel-Gaza conflict","kind":"fact"},{"t":347,"quote":"Major contributors are withholding or delaying payments.","topic":"UN funding","kind":"fact"},{"t":371,"quote":"Norway remains one of the UN's 10 largest donors.","topic":"UN funding","kind":"number"},{"t":432,"quote":"an average developing country hosts no less than 23 different UN organizations","topic":"UN institutional crisis","kind":"number"},{"t":443,"quote":"We also have 10 human rights treaty and 11 secretariats for global environmental treaties","topic":"UN institutional crisis","kind":"number"},{"t":508,"quote":"Grain and fertilizer supplies disrupted by Russia's war against Ukraine undermine food security far beyond Europe's shores.","topic":"Russia-Ukraine war","kind":"fact"},{"t":534,"quote":"What was described by President Putin as a special military operation that would be over in days or maybe weeks is now well into its fifth year.","topic":"Russia-Ukraine war","kind":"fact"},{"t":590,"quote":"The agreement between our neighbor Denmark, Greenland, and the United States serves as an example of how good diplomacy can lead to a lasting solution that respects the interest of all parties while fully respecting their sovereign rights.","topic":"International justice","kind":"fact"},{"t":616,"quote":"The International Criminal Court is one of the most important expressions of this noble quest.","topic":"International justice","kind":"fact"},{"t":656,"quote":"The UN 80 initiative is a test of our ability to build a stronger, more robust Norway supports the level of ambition that the Secretary-General has set out.","topic":"UN reform","kind":"fact"},{"t":677,"quote":"The mandate resolution laid the foundation for better joint decisions.","topic":"UN reform","kind":"fact"},{"t":735,"quote":"The UN 80 process needs to continue under the next Secretary General.","topic":"UN reform","kind":"fact"},{"t":743,"quote":"For an organization of 193 states to function, we need a strong, independent Secretary General that firmly advocates the principles of the UN Charter with integrity and with authority.","topic":"UN reform","kind":"fact"},{"t":795,"quote":"The absence of Africa among the permanent seats of the Council is but one striking example.","topic":"UNSC reform","kind":"fact"},{"t":827,"quote":"While wars and geopolitical tensions dominate the agenda, we must not lose sight of our most important shared responsibility, which is to take better care of the planet on which we all depend.","topic":"UNSC reform","kind":"fact"},{"t":850,"quote":"The catastrophic floods that struck the Himalayas last month is yet another stark reminder of the growing risk associated with climate change.","topic":"Climate change","kind":"fact"},{"t":868,"quote":"We already have the insights and technologies to make this transition And they are increasingly competitive from an economic perspective, as seen by the fast-falling cost falling cost of renewable energy.","topic":"Climate change","kind":"fact"},{"t":920,"quote":"There There nothing inevitable in this Artificial intelligence is developed by humans and must remain under human direction, oversight, and control.","topic":"AI governance","kind":"fact"},{"t":931,"quote":"It is becoming an integral part of our A part of almost all aspects of society and economy.","topic":"AI governance","kind":"fact"},{"t":1030,"quote":"For 80 years, it has proved a space where nations can negotiate instead of fight, cooperate instead of confront, and build rules instead of yielding to law rule power.","topic":"Democracy erosion","kind":"fact"},{"t":1041,"quote":"The world we know today is safer, more prosperous, and more just because the United Nations exist.","topic":"UN institutional crisis","kind":"fact"},{"t":1048,"quote":"The founders of the United Nations as had witnessed two World Wars and a global economic collapse.","topic":"UN institutional crisis","kind":"fact"},{"t":1107,"quote":"The time for reports has passed. The time for action is now.","topic":"UN reform","kind":"fact"}],"promises":[{"t":319,"quote":"We must act now with moral clarity and ensure that the coming year becomes a year of implementation.","topic":"Israel-Gaza conflict","kind":"promise"},{"t":376,"quote":"We will use our funding to support and promote reform.","topic":"UN funding","kind":"promise"},{"t":622,"quote":"Together with so many like-minded countries, we will strengthen our resolve to defend and to further develop the ICC.","topic":"International justice","kind":"promise"},{"t":948,"quote":"This week, Finland and Norway are appealing to businesses, governments, and the UN alike to cooperate for responsible management of the opportunities and the risks of artificial intelligence.","topic":"AI governance","kind":"promise"}],"attacks":[{"t":285,"quote":"When we condemn Russia's clear violation of international law in Ukraine, it is equally important to speak out of Israel's violations of the same rules","topic":"Israel-Gaza conflict","target":"Russia and Israel"},{"t":709,"quote":"But unfortunately, colleagues, too often member states show vested interests, engage themselves in turf battles, and become fearful of change.","topic":"UN reform","target":"Member States"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":"Gramsci quote","text":"And I now give the floor to His Barth Eide, Minister of Foreign Affairs of Norway. &gt;&gt; The old world is dying, and the new world struggles to be born. Now is the time of monsters. distinguished delegates, these words stem from the Italian philosopher Antonio Gramsci, written in one of Mussolini's prison cells in the 1930s. The monsters he refers to were the dark political, social, and ideological phenomena of his time. Gramsci describes a time of transition, of insecurity, and the collapse of hegemonies."},{"t":72,"topic":"UN institutional crisis","text":"His worries were not unwarranted. His era ended with the largest catastrophe of them all, the Second World War. Our United Nations was founded by leaders who had lived through two World a devastating economic collapse, and the rise of fascism and Nazism. They had experienced firsthand that all nations suffer in war and conflict, and when international cooperation fails. We too are living in turbulent times. Yet at the very moment when we need it our United Nations faces its most serious challenge. We see an erosion of respect for international law, a loss of confidence in the merits of of financing, and of effectiveness. These are symptoms of the same disease. A growing belief that power matters more than principle."},{"t":137,"topic":"UN Charter","text":"A growing temptation to seek national advantage at the expense of common But history teaches us a simple lesson. When rules are undermined, instability When cooperation weakens, instability Smaller countries like my own, and in fact, the last the vast majority of this assembly, are particularly dependent on common international rules. But we also learned that all states end up suffering if unchecked violence is Today, the repercussions of ongoing wars are felt across the globe. I am here with one message. We who honor the UN Charter must also stand ready to make some tough Reform is necessary. Not because the United Nations failed, but because it matters. President, today our United Nations finds itself in a triple crisis."},{"t":199,"topic":"International law","text":"It's a normative crisis, it's a financial crisis, and an institutional First, the normative crisis. The fundamental rules that protect the integrity of sovereign state and prohibit the use of force, except in self-defense, are threatened. The number of ongoing wars is alarmingly high. Most dramatically, the number of wars between states is the highest since the United Nations was established. Yet, this was the key motive for establishing this organization in the first place. To save succeeding generations from the scourge of war. International law is not charity to the weak. It's a common investment in a system that reduces risk, friction, and cost for everyone, including the great Take freedom of navigation as an This long-standing principle enshrined in our convention of the law of the sea benefits every state."},{"t":261,"topic":"Israel-Gaza conflict","text":"The Strait of Hormuz shows us why. Its closure raises energy prices, disrupts global supply lines, and curbs growth far beyond the region itself. From petrol pumps in Minneapolis to Oslo, from Cape Town to Mumbai. International law is not a menu you can choose from at will. It must be upheld universally. When we condemn Russia's clear violation of international law in Ukraine, it is equally important to speak out of Israel's violations of the same rules in International law is only relevant if it's enforced. There is no alternative to the two-state At this General Assembly, there's been a record number of Palestine-related The support for a Palestinian state has never been stronger, yet the situation on the ground is more dire than ever. We must act now with moral clarity and ensure that the coming year becomes a year of implementation."},{"t":327,"topic":"UN funding","text":"My message is this. Only if we apply international law to all people, in all places, and at all times, can we claim that these are universal rules. Double standards quickly translate into no standards at all. Secondly, the UN is in a financial crisis. Major contributors are withholding or delaying payments. Wars and security concerns divert resources away from the fulfillment of our sustainable development goals. And when resources are available, they too often come with strict earmarking. We, the donors, should earmark less and allow more flexible use of resources. Norway remains one of the UN's 10 largest donors. We will use our funding to support and promote reform. Because we believe in investing in the We believe that active, constructive implementation of the UN 80 reforms is necessary for its future."},{"t":391,"topic":"UN institutional crisis","text":"This will be a key factor when we assess future voluntary contributions to agencies, funds, and programs. Thirdly, the UN is an in an institutional crisis. I am a strong believer in this But I also recognize that over time, we have added excessive complexity to our United Nations. Too often, when we identify a new challenge or a new idea, we create a new agency, a new convention, a fund, or a program to address it. With then comes with secretariats, staff, resources, and And on the ground, an average developing country hosts no less than 23 different UN organizations. In the most vulnerable states, the number is even higher. We also have 10 human rights treaty and 11 secretariats for global environmental treaties. I pay tribute to the dedicated and serious staff that is representing us all out there, at times in at times very difficult places."},{"t":461,"topic":"Russia-Ukraine war","text":"But those who care about the UN must ask, are we improving delivery or just creating more fragmentation and The United Nations derives its legitimacy from the sovereign equality of states. Yet many member states are struggling to keep pace and to participate. We must simplify. We must focus. We must improve our capacity to deliver as one and create more impact on the ground. We, the member states, must give guidance to the Secretary General in succeeding with the ongoing reform endeavor. At times, this might require a solid doses of tough love. President, the cost of war affects us Grain and fertilizer supplies disrupted by Russia's war against Ukraine undermine food security far beyond Europe's shores. Russia's war against Ukraine and the conflict in the Strait of Hormuz teach us the same lesson."},{"t":524,"topic":"Russia-Ukraine war","text":"When might succeeds over right, we all pay the price. Often, the consequence of war also come home to haunt the aggressor. What was described by President Putin as a special military operation that would be over in days or maybe weeks is now well into its fifth year. Likewise, there is no end in sight for the war in the Gulf. Both wars reminds us about the limitations of military power. Military action is never the goal in Clausewitz described war as the continuation of politics by other means. if the war's political goals cannot be achieved, war just becomes unnecessary death, destruction, and loss. And frankly, demonstrations of weakness. The limited success of these and other ongoing wars is in in itself a strong argument for prevention, mediation, and peace building. Diplomacy can work if we allow it to."},{"t":587,"topic":"International justice","text":"We saw a good example of this this week. The agreement between our neighbor Denmark, Greenland, and the United States serves as an example of how good diplomacy can lead to a lasting solution that respects the interest of all parties while fully respecting their sovereign rights. Colleagues, we need to continue our quest to ensure that there can be no impunity for committing the most grave international crimes. The International Criminal Court is one of the most important expressions of this noble quest. Together with so many like-minded countries, we will strengthen our resolve to defend and to further develop the ICC. Norway resoundingly rejects the calls for dismantling the International Criminal Court. President, the triple crisis I have set out here is no less than an existential crisis for our United Nations. Yet thankfully, to counter this, we have concrete proposals for reform on the table, the UN 80 initiative."},{"t":656,"topic":"UN reform","text":"The UN 80 initiative is a test of our ability to build a stronger, more robust Norway supports the level of ambition that the Secretary-General has set out. We support the proposals across all work streams, including structural changes. The UN 80 process has already produced The mandate resolution laid the foundation for better joint decisions. We all agree that we must rationalize mandates, streamline reporting, and organize our work to allow for broad, effective participation. Norway is proud to play a role in this But we also do need structural structural change. We need to be better at delivering as one. Some UN organizations frankly overlap. They should be merged in order to serve our common interest. But unfortunately, colleagues, too often member states show vested interests, engage themselves in turf battles, and become fearful of change."},{"t":718,"topic":"UN reform","text":"Let me be clear. Reform will not succeed if we always keep protecting the status Let us remind ourselves that we, the member states, are the owners of this organization, not the Secretariat. With that comes responsibility. The UN 80 process needs to continue under the next Secretary General. We need to see this initiative succeed. For an organization of 193 states to function, we need a strong, independent Secretary General that firmly advocates the principles of the UN Charter with integrity and with authority. In a time of geopolitical tension, the Secretary General's good offices function becomes more important than ever before. The next Secretary General will face the formidable task of helping us lead the United Nations out of its current We need someone bold and transformative. She must be able to build trust, to implement our decisions, lead meaningful reform, and improve effectiveness."},{"t":784,"topic":"UNSC reform","text":"A true reform of this organization must also address the composition and functioning of the Security Council. That is the common call of the majority of this room. The absence of Africa among the permanent seats of the Council is but one striking example. While striving to improve legitimacy, we must ensure that we not do not reduce We need a Security Council that is open, transparent, and accountable in its A Security Council that is both legitimate and effective, measured in its ability to take meaningful action. President, there is no lack of challenges to be tackled. While wars and geopolitical tensions dominate the agenda, we must not lose sight of our most important shared responsibility, which is to take better care of the planet on which we all depend. Climate change, biodiversity loss, and rampant pollution threatens life, property, and prosperity everywhere."},{"t":850,"topic":"Climate change","text":"The catastrophic floods that struck the Himalayas last month is yet another stark reminder of the growing risk associated with climate change. The good news is that reducing emissions and ensuring a more responsible management of the world's natural resources is possible. We already have the insights and technologies to make this transition And they are increasingly competitive from an economic perspective, as seen by the fast-falling cost falling cost of renewable energy. But we can only succeed if we cooperate. We cannot put fences around our climate around climate, our own biosphere, or deal with the ills of our oceans on our we live in an era of artificial intelligence. As the Secretary-General uh said it in his speech, the danger is not technology. The The danger is technology without accountability."},{"t":912,"topic":"AI governance","text":"I agree. Colleagues, we should not panic. But we must be determined. There There nothing inevitable in this Artificial intelligence is developed by humans and must remain under human direction, oversight, and control. It is becoming an integral part of our A part of almost all aspects of society and economy. And as we have done so many times before, we must maximize the positive benefits of emerging technologies while curbing its darker potentials. This week, Finland and Norway are appealing to businesses, governments, and the UN alike to cooperate for responsible management of the opportunities and the risks of artificial intelligence. Defense of essential human values goes well beyond regulating technology. For decades, we saw a growth in democratic governance, respect for the rule of law, and respect for human rights."},{"t":975,"topic":"Democracy erosion","text":"Sadly, this trend have no turn. Democratic backsliding, polarization, and weakening weakening of our democratic shields challenges many of our past achievements. Increasing economic inequality in countries exacerbate this trend. We should take democratic backsliding very seriously. While this may be may seem to be domestic concern, we know that the way states behave internationally reflects from the on their domestic politics. Authoritarian and exclusivist sentiments within member states will therefore also affect our capacity to address our shared concerns. President, the United Nations is one of humanity's greatest achievements. Not because it created a perfect world. It did not. But because it helped spare us from a far worse fate. For 80 years, it has proved a space where nations can negotiate instead of fight, cooperate instead of confront, and build rules instead of yielding to law rule power."},{"t":1041,"topic":"UN institutional crisis","text":"The world we know today is safer, more prosperous, and more just because the United Nations exist. The founders of the United Nations as had witnessed two World Wars and a global economic collapse. They knew something we must never When law gives way to force, everybody When cooperation collapses, everybody pays. When institutions fail, chaos They did not build the United Nations because they believed mankind was perfect. They built it because they understood mankind is not. They built it because they know knew that without rules, without dialogue, without cooperation, history has a habit of repeating its darkest The responsibility is now ours. Not only the Secretary General's. The United Nations belong to the member We decide whether it succeed or fails."},{"t":1102,"topic":"UN reform","text":"We decide whether reform advances or The time for reports has passed. The time for action is now. It is our turn to face the monsters of our time. &gt;&gt; I thank the Minister of Foreign Affairs of Norway."}],"compare":[{"topic":"UN & its reform","share":0.5158,"mean":0.2031,"rank":4,"others":170},{"topic":"International Law & Order","share":0.186,"mean":0.0597,"rank":19,"others":102},{"topic":"Russia-Ukraine War","share":0.1193,"mean":0.0349,"rank":20,"others":44},{"topic":"Israel–Palestine","share":0.0609,"mean":0.0524,"rank":61,"others":76},{"topic":"Artificial Intelligence","share":0.0597,"mean":0.0504,"rank":66,"others":83},{"topic":"Climate Change","share":0.0583,"mean":0.0427,"rank":56,"others":77}]};
